            "views": [
                {
                    "table_name": "pg_stat_statements",
                    "table_schema": "extensions",
                    "view_definition": " SELECT userid,\n    dbid,\n    toplevel,\n    queryid,\n    query,\n    plans,\n    total_plan_time,\n    min_plan_time,\n    max_plan_time,\n    mean_plan_time,\n    stddev_plan_time,\n    calls,\n    total_exec_time,\n    min_exec_time,\n    max_exec_time,\n    mean_exec_time,\n    stddev_exec_time,\n    rows,\n    shared_blks_hit,\n    shared_blks_read,\n    shared_blks_dirtied,\n    shared_blks_written,\n    local_blks_hit,\n    local_blks_read,\n    local_blks_dirtied,\n    local_blks_written,\n    temp_blks_read,\n    temp_blks_written,\n    shared_blk_read_time,\n    shared_blk_write_time,\n    local_blk_read_time,\n    local_blk_write_time,\n    temp_blk_read_time,\n    temp_blk_write_time,\n    wal_records,\n    wal_fpi,\n    wal_bytes,\n    jit_functions,\n    jit_generation_time,\n    jit_inlining_count,\n    jit_inlining_time,\n    jit_optimization_count,\n    jit_optimization_time,\n    jit_emission_count,\n    jit_emission_time,\n    jit_deform_count,\n    jit_deform_time,\n    stats_since,\n    minmax_stats_since\n   FROM pg_stat_statements(true) pg_stat_statements(userid, dbid, toplevel, queryid, query, plans, total_plan_time, min_plan_time, max_plan_time, mean_plan_time, stddev_plan_time, calls, total_exec_time, min_exec_time, max_exec_time, mean_exec_time, stddev_exec_time, rows, shared_blks_hit, shared_blks_read, shared_blks_dirtied, shared_blks_written, local_blks_hit, local_blks_read, local_blks_dirtied, local_blks_written, temp_blks_read, temp_blks_written, shared_blk_read_time, shared_blk_write_time, local_blk_read_time, local_blk_write_time, temp_blk_read_time, temp_blk_write_time, wal_records, wal_fpi, wal_bytes, jit_functions, jit_generation_time, jit_inlining_count, jit_inlining_time, jit_optimization_count, jit_optimization_time, jit_emission_count, jit_emission_time, jit_deform_count, jit_deform_time, stats_since, minmax_stats_since);"
                },
                {
                    "table_name": "pg_stat_statements_info",
                    "table_schema": "extensions",
                    "view_definition": " SELECT dealloc,\n    stats_reset\n   FROM pg_stat_statements_info() pg_stat_statements_info(dealloc, stats_reset);"
                },
                {
                    "table_name": "ledger_balances",
                    "table_schema": "public",
                    "view_definition": " SELECT currency,\n    sum(\n        CASE\n            WHEN (direction = 'credit'::text) THEN amount\n            ELSE (- amount)\n        END) AS balance,\n    count(*) AS entry_count,\n    max(created_at) AS last_entry_at\n   FROM ledger_entries le\n  GROUP BY currency;"
                },
                {
                    "table_name": "v_customer_layby_outstanding",
                    "table_schema": "public",
                    "view_definition": " SELECT l.id AS layby_id,\n    l.customer_id,\n    l.status AS layby_status,\n    l.notes AS layby_notes,\n    COALESCE(f.total_due, l.total_amount, (0)::numeric) AS layby_total_due,\n    COALESCE(f.paid_amount, l.paid_amount, (0)::numeric) AS layby_paid_amount,\n    COALESCE(f.outstanding_amount, GREATEST((0)::numeric, (COALESCE(l.total_amount, (0)::numeric) - COALESCE(l.paid_amount, (0)::numeric))), (0)::numeric) AS layby_outstanding,\n    ( SELECT min(s.sale_date) AS min\n           FROM sales s\n          WHERE ((s.layby_id = l.id) OR (s.id = l.sale_id))) AS first_sale_date,\n    ( SELECT max(s.sale_date) AS max\n           FROM sales s\n          WHERE ((s.layby_id = l.id) OR (s.id = l.sale_id))) AS last_sale_date,\n    ( SELECT max(sp.payment_date) AS max\n           FROM (sales_payments sp\n             JOIN sales s ON ((s.id = sp.sale_id)))\n          WHERE ((s.layby_id = l.id) OR (s.id = l.sale_id))) AS last_payment_at\n   FROM (laybys l\n     LEFT JOIN v_sales_pdf_totals f ON ((f.sale_id = l.sale_id)));"
                },
                {
                    "table_name": "v_factory_sold_storage_active",
                    "table_schema": "public",
                    "view_definition": " SELECT id,\n    sale_id,\n    sale_item_id,\n    product_id,\n    location_id,\n    quantity,\n    quantity_released,\n    status,\n    stored_at,\n    expected_release_date,\n    released_at,\n    release_reference,\n    customer_name,\n    customer_phone,\n    notes,\n    metadata,\n    created_by,\n    created_by_user_id,\n    updated_by,\n    updated_by_user_id,\n    updated_at\n   FROM factory_sold_storage_items f\n  WHERE ((status = ANY (ARRAY['stored'::text, 'partial'::text])) AND (GREATEST((COALESCE(quantity, (0)::numeric) - COALESCE(quantity_released, (0)::numeric)), (0)::numeric) > (0)::numeric));"
                },
                {
                    "table_name": "v_factory_sold_storage_summary",
                    "table_schema": "public",
                    "view_definition": " SELECT product_id,\n    location_id,\n    sum(COALESCE(quantity, (0)::numeric)) AS total_qty_stored,\n    sum(COALESCE(quantity_released, (0)::numeric)) AS total_qty_released,\n    sum(GREATEST((COALESCE(quantity, (0)::numeric) - COALESCE(quantity_released, (0)::numeric)), (0)::numeric)) AS qty_on_hold,\n    count(*) FILTER (WHERE (status = ANY (ARRAY['stored'::text, 'partial'::text]))) AS holding_rows,\n    min(stored_at) AS first_stored_at,\n    max(updated_at) AS last_activity_at\n   FROM factory_sold_storage_items f\n  GROUP BY product_id, location_id;"
                },
                {
                    "table_name": "v_location_transfer_totals",
                    "table_schema": "public",
                    "view_definition": " SELECT location_id,\n    COALESCE(sum(transfer_in_qty), (0)::numeric) AS transfer_in_qty,\n    COALESCE(sum(transfer_out_qty), (0)::numeric) AS transfer_out_qty\n   FROM ( SELECT sts.to_location AS location_id,\n            COALESCE(sum(ste.quantity), (0)::numeric) AS transfer_in_qty,\n            (0)::numeric AS transfer_out_qty\n           FROM (stock_transfer_entries ste\n             JOIN stock_transfer_sessions sts ON ((sts.id = ste.session_id)))\n          GROUP BY sts.to_location\n        UNION ALL\n         SELECT sts.from_location AS location_id,\n            (0)::numeric AS transfer_in_qty,\n            COALESCE(sum(ste.quantity), (0)::numeric) AS transfer_out_qty\n           FROM (stock_transfer_entries ste\n             JOIN stock_transfer_sessions sts ON ((sts.id = ste.session_id)))\n          GROUP BY sts.from_location) loc\n  GROUP BY location_id;"
                },
                {
                    "table_name": "v_negative_inventory",
                    "table_schema": "public",
                    "view_definition": " SELECT i.product_id,\n    p.name AS product_name,\n    p.sku,\n    i.location,\n    l.name AS location_name,\n    i.quantity,\n    now() AS snapshot_at,\n        CASE\n            WHEN (i.quantity < 0) THEN 'negative'::text\n            ELSE 'zero'::text\n        END AS severity\n   FROM ((inventory i\n     LEFT JOIN products p ON ((p.id = i.product_id)))\n     LEFT JOIN locations l ON ((l.id = i.location)))\n  WHERE (COALESCE(i.quantity, 0) <= 0);"
                },
                {
                    "table_name": "v_payments_non_credit",
                    "table_schema": "public",
                    "view_definition": " SELECT id,\n    sale_id,\n    amount,\n    payment_type,\n    payment_date,\n    reference,\n    notes,\n    currency\n   FROM sales_payments sp\n  WHERE (lower(COALESCE(payment_type, ''::text)) <> 'credit'::text);"
                },
                {
                    "table_name": "v_sales_financials",
                    "table_schema": "public",
                    "view_definition": " SELECT s.id AS sale_id,\n    s.customer_id,\n    s.location_id,\n    s.sale_date,\n    s.status,\n    s.currency,\n    f.subtotal_before_discount,\n    f.discount_amount,\n    f.total_due AS net_after_discount,\n    f.total_due,\n    f.paid_amount,\n    f.outstanding_amount,\n    NULL::numeric AS vat_amount,\n    ( SELECT max(sp.payment_date) AS max\n           FROM sales_payments sp\n          WHERE (sp.sale_id = s.id)) AS last_payment_at\n   FROM (sales s\n     LEFT JOIN v_sales_pdf_totals f ON ((f.sale_id = s.id)));"
                },
                {
                    "table_name": "v_sales_financials_canonical",
                    "table_schema": "public",
                    "view_definition": " SELECT s.id AS sale_id,\n    s.customer_id,\n    s.layby_id,\n    s.sale_date,\n    s.status,\n    s.currency,\n    f.total_due,\n    f.paid_amount,\n    f.outstanding_amount\n   FROM (sales s\n     LEFT JOIN v_sales_pdf_totals f ON ((f.sale_id = s.id)));"
                },
                {
                    "table_name": "v_sales_pdf_totals",
                    "table_schema": "public",
                    "view_definition": " WITH item_totals AS (\n         SELECT si.sale_id,\n            sum((COALESCE(si.unit_price, (0)::numeric) * (COALESCE(si.quantity, 0))::numeric)) AS subtotal_before_discount\n           FROM sales_items si\n          GROUP BY si.sale_id\n        ), payment_totals AS (\n         SELECT sp.sale_id,\n            sum(COALESCE(sp.amount, (0)::numeric)) AS paid_amount\n           FROM sales_payments sp\n          WHERE (lower(COALESCE(sp.payment_type, ''::text)) <> 'credit'::text)\n          GROUP BY sp.sale_id\n        )\n SELECT s.id AS sale_id,\n    s.currency,\n    COALESCE(it.subtotal_before_discount, s.total_amount, (0)::numeric) AS subtotal_before_discount,\n    COALESCE(s.discount, (0)::numeric) AS discount_amount,\n    GREATEST((0)::numeric, (COALESCE(it.subtotal_before_discount, s.total_amount, (0)::numeric) - LEAST(COALESCE(s.discount, (0)::numeric), COALESCE(it.subtotal_before_discount, s.total_amount, (0)::numeric)))) AS total_due,\n    COALESCE(pt.paid_amount, (0)::numeric) AS paid_amount,\n    GREATEST((0)::numeric, (GREATEST((0)::numeric, (COALESCE(it.subtotal_before_discount, s.total_amount, (0)::numeric) - LEAST(COALESCE(s.discount, (0)::numeric), COALESCE(it.subtotal_before_discount, s.total_amount, (0)::numeric)))) - COALESCE(pt.paid_amount, (0)::numeric))) AS outstanding_amount\n   FROM ((sales s\n     LEFT JOIN item_totals it ON ((it.sale_id = s.id)))\n     LEFT JOIN payment_totals pt ON ((pt.sale_id = s.id)));"
                },
                {
                    "table_name": "v_sales_totals_canonical",
                    "table_schema": "public",
                    "view_definition": " SELECT s.id AS sale_id,\n    s.customer_id,\n    s.layby_id,\n    s.sale_date,\n    s.status,\n    s.currency,\n    f.total_due\n   FROM (sales s\n     LEFT JOIN v_sales_pdf_totals f ON ((f.sale_id = s.id)));"
                },
                {
                    "table_name": "v_transfer_sessions_totals",
                    "table_schema": "public",
                    "view_definition": " SELECT sts.id AS session_id,\n    sts.from_location,\n    sts.to_location,\n    COALESCE(sum(ste.quantity), (0)::numeric) AS total_qty\n   FROM (stock_transfer_sessions sts\n     LEFT JOIN stock_transfer_entries ste ON ((ste.session_id = sts.id)))\n  GROUP BY sts.id, sts.from_location, sts.to_location;"
                }
            ],
